def _integrate_program(lane: str, parameters: Mapping[str, Any], initial: Mapping[str, float], process: ProcessSpec, *, ph_drift: Optional[PhDrift]=None, trunk_draw: Optional[Tuple[Optional[float], Optional[float]]]=None, acrylamide_draw: Optional[Dict[str, Optional[float]]]=None, reservoir_scale: Optional[float]=None) -> Tuple[Dict[str, float], Dict[str, Any]]:
    state: Dict[str, float] = dict(initial)
    metadata: Dict[str, Any] = {'segments': [], 'lane': lane}
    if lane == SULFUR:
        state.setdefault('OX', OX_AMBIENT_MMOL_L)
        if 'PROT_SS' not in state:
            from .matrix_sites import resolve as _resolve_sites
            charged, _note = _resolve_sites(process)
            if charged is not None and charged.disulfide > 0:
                state['PROT_SS'] = float(charged.disulfide)
        if 'OXR' not in state:
            reservoir, _basis = oxygen_reservoir_units(process)
            state['OXR'] = reservoir * (1.0 if reservoir_scale is None else float(reservoir_scale))
        state.setdefault('OXV', 0.0)
    if lane != TRUNK:
        for key in ('MET', 'PRO', 'PYRL'):
            if key in state:
                metadata.setdefault('recorded_not_charged', {})[key] = float(state.pop(key))
    if lane == TRUNK and state.get('PRO', 0.0) > 0.0:
        state['Gly'] = float(state.get('Gly', 0.0)) + float(state['PRO'])
    if lane == TRUNK and state.get('MET', 0.0) > 0.0:
        state['Gly'] = float(state.get('Gly', 0.0)) + float(state['MET'])
    if lane == TRUNK and 'LYSP' not in state:
        from .matrix_sites import resolve as _resolve_sites
        from .parameters_glycation import available_fraction
        try:
            charged, _note = _resolve_sites(process)
        except Exception:
            charged = None
        if charged is not None and charged.amine > 0:
            state['LYSP'] = float(charged.amine) * available_fraction(charged.amine_band)
    sulfur_sid: Optional[float] = None
    thermal = process.thermal
    if lane == SULFUR and thermal.profile is not None:
        segment_list = [(thermal.total_minutes, thermal.peak_temperature_c)]
        profile_k = (np.array([t for t, _ in thermal.profile]), np.array([c for _, c in thermal.profile]) + CELSIUS)
    else:
        segment_list = list(thermal.segments)
        profile_k = None
    for index, (duration, temperature_c) in enumerate(segment_list):
        grid = np.array([0.0, float(duration)])
        if lane == SULFUR:
            run = integrate_sulfur(parameters, float(temperature_c) + CELSIUS, state, grid, ph=float(process.ph), ph_final=float(process.ph_final) if process.ph_final is not None else None, buffer_spec=process.buffer if process.buffer is not None else DEFAULT_BUFFER, ph_drift=process.ph_drift if process.ph_drift is not None else ph_drift if ph_drift is not None else core_ph_drift(), rtol=1e-08, atol=1e-14, sid_mmol_l=sulfur_sid, temperature_profile=profile_k)
            if sulfur_sid is None:
                sulfur_sid = run.metadata.get('strong_ion_difference_mmol_L')
            keys = list(SULFUR_INDEX)
        elif lane == ACRYLAMIDE:
            d = acrylamide_draw or {}
            acr_parameters, condition_terms = acrylamide_conditions.apply(parameters, process, aw_scale=d.get('aw_scale'), aw_elimination_deficit_scale=1.0 if d.get('aw_elimination_scale') is None else float(d['aw_elimination_scale']), ph_exponent_formation=acrylamide_conditions.PH_EXPONENT_FORMATION if d.get('ph_exponent_formation') is None else float(d['ph_exponent_formation']), ph_exponent_elimination=acrylamide_conditions.PH_EXPONENT_ELIMINATION if d.get('ph_exponent_elimination') is None else float(d['ph_exponent_elimination']), ea_overrides={'k_int1_acr': d.get('ea_int1'), 'k_asn_glc': d.get('ea_asn_glc')})
            if condition_terms:
                metadata.setdefault('condition_terms', list(condition_terms))
            run = integrate_acrylamide(acr_parameters, float(temperature_c) + CELSIUS, state, grid, water_activity=process.water_activity, rtol=1e-08, atol=1e-14)
            keys = list(ACRYLAMIDE_INDEX)
        else:
            aw_scale, ph_exponent = trunk_draw or (None, None)
            trunk_parameters, condition_terms = trunk_conditions.apply(parameters, process, aw_scale=1.0 if aw_scale is None else float(aw_scale), ph_exponent=trunk_conditions.PH_EXPONENT_DECADES_PER_UNIT if ph_exponent is None else float(ph_exponent))
            metadata.setdefault('condition_terms', list(condition_terms))
            run = integrate(trunk_parameters, float(temperature_c) + CELSIUS, state, grid, rtol=1e-08, atol=1e-14)
            keys = list(SPECIES_KEYS)
        state = {key: float(run.concentrations[-1, i]) for i, key in enumerate(keys)}
        metadata['segments'].append({'index': index, 'duration_min': float(duration), 'temperature_C': float(temperature_c), 'extrapolation_warnings': list(run.metadata.get('extrapolation_warnings', [])), 'ph_mode': run.metadata.get('ph_mode'), 'ph_in_situ_start': run.metadata.get('ph_initial_in_situ'), 'ph_in_situ_end': run.metadata.get('ph_final_in_situ'), 'ph_cooled_end': run.metadata.get('ph_final_cooled'), 'ph_notes': list(run.metadata.get('ph_notes', []))})
    return (state, metadata)

