def ph_factor(kind: str, ph: float, temperature_k: float=T_REF_S_K, ionic_strength_m: float=0.0) -> float:
    t_k = float(temperature_k)
    i_m = float(ionic_strength_m)
    if kind == '':
        return 1.0
    if kind == 'acid':
        return 10.0 ** (PH_NORMALISATION - float(ph))
    if kind == 'base':
        return free_amine_fraction(ph, t_k, i_m) / free_amine_fraction(PH_NORMALISATION, t_k)
    if kind == 'hydroxide':
        return 10.0 ** (float(ph) - PH_NORMALISATION)
    if kind == 'neutral_h2s':
        return neutral_h2s_fraction(ph, t_k, i_m) / neutral_h2s_fraction(PH_NORMALISATION, t_k)
    if kind == 'hs_anion':
        return hydrosulfide_fraction(ph, t_k, i_m) / hydrosulfide_fraction(PH_NORMALISATION, t_k)
    if kind == 'thiolate':
        return thiolate_fraction(ph, t_k, i_m) / thiolate_fraction(PH_NORMALISATION, t_k)
    raise ValueError(f'unknown pH factor kind {kind!r}')

def pka_at(name: str, temperature_k: float, ionic_strength_m: float=0.0) -> float:
    if name not in PKA_25C:
        raise KeyError(f'no pKa registered for {name!r}')
    b51 = _ph.B51
    if name == 'h2s_1' and b51.h2s_suleimenov:
        pk = h2s_pk1_suleimenov_seward(temperature_k)
    elif name in PKA_GKL_CYSTEINE and b51.cysteine_gkl:
        pk25, dh, dcp = PKA_GKL_CYSTEINE[name]
        pk = _ph.pk_at(pk25, dh, dcp, temperature_k)
    else:
        shift = float(DELTA_H_IONISATION_KJ_MOL[name]) / (R_KJ * math.log(10.0)) * (1.0 / float(temperature_k) - 1.0 / PKA_REFERENCE_T_K)
        pk = float(PKA_25C[name]) + shift
    return pk - _ph.davies_term(ionic_strength_m, temperature_k)

