def thiamine_h2s_share(ph: float) -> float:
    (p0, f0), (p1, f1) = THIAMINE_H2S_SHARE_POINTS
    x = float(ph)
    if x < THIAMINE_H2S_SHARE_FLOOR_PH:
        return 0.0
    if x >= p1:
        return f1
    return 10.0 ** (math.log10(f0) + (x - p0) / (p1 - p0) * (math.log10(f1) - math.log10(f0)))

