def _bisect_ph(temperature_k, sid_mmol_l, inventory, ionic, lo, hi, tol, max_iter) -> float:
    residual = _residual_at_fixed_conditions(temperature_k, sid_mmol_l, inventory, ionic)
    f_lo = residual(lo)
    f_hi = residual(hi)
    if f_lo < 0.0:
        return lo
    if f_hi > 0.0:
        return hi
    for _ in range(max_iter):
        mid = 0.5 * (lo + hi)
        if hi - lo < tol:
            return mid
        if residual(mid) > 0.0:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)

