def titratable_inventory(concentrations: Mapping[str, float], drift: PhDrift, buffer_spec: BufferSpec) -> Tuple[Tuple[TitratableGroup, float], ...]:
    out: list = []
    yield_ = float(drift.acid_yield)
    lumped = yield_ * float(concentrations.get('ACID', 0.0))
    for group, share in ORGANIC_ACID_MIX:
        if lumped > 0.0:
            out.append((group, share * lumped))
    formic = float(concentrations.get('FA', 0.0))
    acetic = float(concentrations.get('AA', 0.0))
    if formic > 0.0:
        out.append((FORMIC, formic))
    if acetic > 0.0:
        out.append((ACETIC, acetic))
    cys = float(concentrations.get('Cys', 0.0))
    if cys > 0.0:
        out.append((cysteine_group(), cys))
    arp = float(concentrations.get('ARP', 0.0))
    if arp > 0.0:
        out.append((drift.arp_group(), arp))
    ttca = float(concentrations.get('TTCA', 0.0))
    if ttca > 0.0:
        out.append((TTCA_GROUP, ttca))
    cama = float(concentrations.get('CAMA', 0.0))
    if cama > 0.0:
        out.append((drift.arp_group(), cama))
    if TRUNK_SOLUTES_IN_BALANCE:
        gly = float(concentrations.get('Gly', 0.0))
        if gly > 0.0:
            out.append((GLYCINE, gly))
        for key in ('AMA', 'SB', 'PAMA'):
            amount = float(concentrations.get(key, 0.0))
            if amount > 0.0:
                out.append((DFG_GROUP, amount))
    nh4 = float(concentrations.get('NH4', 0.0))
    if nh4 > 0.0:
        out.append((AMMONIUM, nh4))
    returned = float(concentrations.get('RET_AA', 0.0))
    if returned > 0.0:
        out.append((GLYCINE, returned))
    carried_acid = float(concentrations.get('CBX', 0.0))
    if carried_acid > 0.0:
        for group, share in ORGANIC_ACID_MIX:
            out.append((group, share * carried_acid))
    out.extend(buffer_spec.groups())
    return tuple(out)

