def _rates_vectorised(y: np.ndarray, kv: np.ndarray) -> np.ndarray:
    terms = np.append(np.clip(y, 0.0, None), 1.0)[_R_IDX] ** _R_POW
    return kv * np.prod(terms, axis=1)

