def _solve_on_time_nodes(k_nodes: np.ndarray, node_times: np.ndarray, y0: np.ndarray, t_eval: np.ndarray, duration: float, method: str, rtol: float, atol: float):
    from scipy.integrate import solve_ivp

    def rhs(t: float, y: np.ndarray) -> np.ndarray:
        return sulfur_derivatives(y, rate_vector_at(node_times, k_nodes, t))
    return solve_ivp(rhs, (0.0, duration), y0, t_eval=t_eval, method=method, rtol=rtol, atol=atol)

