def integrate_sulfur(parameters: Mapping[str, Any], temperature_k: float, initial: Mapping[str, float], times_min: Sequence[float], *, ph: float=5.0, ph_final: Optional[float]=None, buffer_spec: Optional[BufferSpec]=None, ph_drift: Optional[PhDrift]=None, method: str='LSODA', rtol: float=1e-09, atol: float=1e-12, ph_nodes: int=41, ph_iterations: int=3, sid_mmol_l: Optional[float]=None, temperature_profile: Optional[Tuple[Sequence[float], Sequence[float]]]=None, clamp_ph_label: Optional[float]=None) -> SulfurRun:
    if method not in ('LSODA', 'BDF', 'Radau'):
        raise ValueError(f'method {method!r} is not a stiff-capable solver')
    grid = np.asarray(times_min, dtype=float)
    if grid.ndim != 1 or grid.size == 0:
        raise ValueError('times_min must be a non-empty 1-D sequence')
    if np.any(np.diff(grid) < 0):
        raise ValueError('times_min must be non-decreasing')
    if grid[0] < 0:
        raise ValueError('times_min must start at or after 0')
    duration = float(max(grid[-1], 1e-12))
    ph0 = float(ph)
    y0 = initial_sulfur_state(initial)
    t_k = float(temperature_k)
    profile = _checked_profile(temperature_profile, duration)

    def _with_profile_nodes(nodes: np.ndarray) -> np.ndarray:
        if profile is None:
            return nodes
        return np.unique(np.concatenate([nodes, profile_node_times(*profile, duration)]))

    def _node_temperatures(nodes: np.ndarray) -> np.ndarray:
        if profile is None:
            return np.full(len(nodes), t_k)
        return np.interp(nodes, profile[0], profile[1])
    spec = buffer_spec if buffer_spec is not None else DEFAULT_BUFFER
    dynamic = ph_drift is not None and (not spec.is_clamped)
    rivals = _pbr.any_active()
    if rivals and (not (dynamic and PH_COUPLING == 'inline')):
        raise ValueError(f"an M1b charge-balance rival (ph_balance_rivals) runs only on the inline dynamic pH; this run is {('dynamic' if dynamic else 'clamped or prescribed')} on {PH_COUPLING!r}")
    rival_pools: Optional[Dict[str, np.ndarray]] = None
    rival_diagnostics: Optional[Dict[str, Any]] = None
    ph_notes: list = []
    if buffer_spec is None and ph_drift is not None:
        ph_notes.append(BUFFER_ABSENT_WARNING)
    if dynamic and ph_final is not None:
        ph_notes.append('a measured final pH was supplied AND the dynamic pH state is active; the measured value was IGNORED and the endpoint is a PREDICTION.')
    ph_series: Optional[np.ndarray] = None
    ph_convergence: Optional[float] = None
    sid: Optional[float] = None
    if dynamic:
        assert ph_drift is not None
        node_times = _with_profile_nodes(ph_node_times(duration, max(int(ph_nodes), 5)))
        node_tk = _node_temperatures(node_times)
        n_nodes = len(node_times)
        eval_times = np.unique(np.concatenate([grid, node_times]))
        initial_map = {key: float(y0[SULFUR_INDEX[key]]) for key in SULFUR_STATE_KEYS}
        if sid_mmol_l is not None and _ph.B51.sid_across_segments:
            sid = float(sid_mmol_l)
        else:
            sid = strong_ion_difference(ph0, initial_map, ph_drift, spec)

        def _node_state(state_map, temperature):
            p_hot, i_hot = ph_and_ionic_strength_of_state(state_map, temperature, sid, ph_drift, spec)
            p_cool = ph_of_state(state_map, LABEL_TEMPERATURE_K, sid, ph_drift, spec) if _ph.B51.label_scale_tables else None
            return (p_hot, i_hot, p_cool)
        if profile is None or PH_COUPLING == 'inline':
            p0, i0, c0 = _node_state(initial_map, float(node_tk[0]))
            node_ph = np.full(n_nodes, p0)
            node_i = np.full(n_nodes, i0)
            node_cool = [c0] * n_nodes
        else:
            starts = [_node_state(initial_map, float(tk)) for tk in node_tk]
            node_ph = np.array([s[0] for s in starts])
            node_i = np.array([s[1] for s in starts])
            node_cool = [s[2] for s in starts]
        solution = None
        relaxed = PH_FIXED_POINT == 'relaxed_converged'
        if not relaxed and PH_FIXED_POINT != 'fixed_sweeps':
            raise ValueError(f'unknown PH_FIXED_POINT {PH_FIXED_POINT!r}')
        if PH_COUPLING not in ('fixed_point_nodes', 'inline'):
            raise ValueError(f'unknown PH_COUPLING {PH_COUPLING!r}')
        min_sweeps = max(int(ph_iterations), 1)
        max_sweeps = max(min_sweeps, PH_FIXED_POINT_MAX_SWEEPS) if relaxed else min_sweeps
        sweeps_run = 0
        if PH_COUPLING == 'inline':
            if profile is None:

                def temperature_of(t):
                    return t_k
            else:

                def temperature_of(t):
                    return float(np.interp(t, profile[0], profile[1]))
            if rivals:
                solution, node_ph, node_i, node_cool, k_nodes, rival_pools, rival_diagnostics = _pbr.integrate_inline(parameters, y0, eval_times, duration, temperature_of, sid, ph_drift, spec, method, rtol, atol)
            else:
                solution, node_ph, node_i, node_cool, k_nodes = _integrate_inline_ph(parameters, y0, eval_times, duration, temperature_of, sid, ph_drift, spec, method, rtol, atol)
            node_times = eval_times
            n_nodes = len(node_times)
            ph_convergence = 0.0
            max_sweeps = 0
        for sweep in range(max_sweeps):
            sweeps_run = sweep + 1
            k_nodes = np.array([rate_vector(sulfur_rate_constants_at(parameters, float(tk), float(p), ph_label=c, ionic_strength_m=float(i))) for p, i, c, tk in zip(node_ph, node_i, node_cool, node_tk)])
            solution = _solve_on_time_nodes(k_nodes, node_times, y0, eval_times, duration, method, rtol, atol)
            if not solution.success:
                raise RuntimeError(f'sulfur-network integration failed: {solution.message}')
            states = np.clip(solution.y.T, 0.0, None)
            fresh = np.empty(n_nodes)
            for j, t_node in enumerate(node_times):
                index = int(np.searchsorted(eval_times, t_node))
                index = min(index, len(eval_times) - 1)
                row = states[index]
                fresh[j], node_i[j], node_cool[j] = _node_state({k: float(row[SULFUR_INDEX[k]]) for k in SULFUR_STATE_KEYS}, float(node_tk[j]))
            ph_convergence = float(np.max(np.abs(fresh - node_ph)))
            if relaxed:
                node_ph = node_ph + PH_FIXED_POINT_RELAXATION * (fresh - node_ph)
                if ph_convergence < PH_FIXED_POINT_TOLERANCE and sweeps_run >= min_sweeps:
                    break
            else:
                node_ph = fresh
                if ph_convergence < 0.0001:
                    break
        assert solution is not None
        keep = np.searchsorted(eval_times, grid)
        keep = np.clip(keep, 0, len(eval_times) - 1)
        raw = np.clip(solution.y.T, 0.0, None)[keep]
        worst_negative = float(np.min(solution.y)) if solution.y.size else 0.0
        ph_series = np.interp(grid, node_times, node_ph)
        ph1 = float(ph_series[-1])
    else:
        ph1 = ph0 if ph_final is None else float(ph_final)
        if profile is not None:
            n_nodes = max(int(ph_nodes), 5)
            node_times = _with_profile_nodes(np.linspace(0.0, duration, n_nodes))
            node_ph_line = ph0 + (ph1 - ph0) * node_times / duration
            k_nodes = np.array([rate_vector(sulfur_rate_constants_at(parameters, float(tk), float(p))) for tk, p in zip(_node_temperatures(node_times), node_ph_line)])
        elif ph1 == ph0:
            k_fixed = rate_vector(sulfur_rate_constants_at(parameters, t_k, ph0, ph_label=clamp_ph_label))
            node_times = np.array([0.0, duration])
            k_nodes = np.array([k_fixed, k_fixed])
        else:
            n_nodes = max(int(ph_nodes), 5)
            node_times = np.linspace(0.0, duration, n_nodes)
            k_nodes = np.array([rate_vector(sulfur_rate_constants_at(parameters, t_k, float(p))) for p in np.linspace(ph0, ph1, n_nodes)])
        solution = _solve_on_time_nodes(k_nodes, node_times, y0, grid, duration, method, rtol, atol)
        if not solution.success:
            raise RuntimeError(f'sulfur-network integration failed: {solution.message}')
        raw = solution.y.T
        worst_negative = float(np.min(raw)) if raw.size else 0.0
    if worst_negative < -max(1000.0 * atol, 1e-08):
        raise RuntimeError(f'sulfur-network integration produced a state of {worst_negative:.3e}, far below the absolute tolerance {atol:.1e}: a genuine non-negativity failure, not solver noise.')
    concentrations = np.clip(raw, 0.0, None)
    temperature_c = t_k - 273.15
    metadata: Dict[str, Any] = {'method': method, 'temperature_C': temperature_c, 'temperature_K': t_k, 'temperature_profile_K': None if profile is None else [[float(a), float(b)] for a, b in zip(profile[0], profile[1])], 'ph_initial': ph0, 'ph_final': ph1, 'ph_is_clamped': not dynamic and ph1 == ph0, 'ph_mode': 'dynamic_charge_balance' if dynamic else 'prescribed_measured_endpoints' if ph1 != ph0 else 'clamped', 'ph_notes': ph_notes, 'buffer': spec.as_dict(), 'n_species': N_SULFUR_STATE, 'n_reactions': len(FULL_REACTIONS), 'species_order': list(SULFUR_STATE_KEYS), 'worst_raw_negative_before_clip': worst_negative, 'extrapolation_warnings': _sulfur_extrapolation_warnings(parameters, temperature_c, ph0), 'out_of_scope': [dict(row) for row in OUT_OF_SCOPE]}
    if dynamic:
        assert ph_drift is not None
        final_map = {key: float(concentrations[-1, SULFUR_INDEX[key]]) for key in SULFUR_STATE_KEYS}
        if rival_pools is not None:
            pool_grid = {k: np.clip(v[keep], 0.0, None) for k, v in rival_pools.items()}
            final_map.update(_pbr.balance_pools({k: float(v[-1]) for k, v in pool_grid.items()}))
            metadata['ph_balance_rivals'] = {'switches': _pbr.switches_record(), 'pools': {k: [float(x) for x in v] for k, v in pool_grid.items()}, 'diagnostics': rival_diagnostics, 'note': "the pools are bookkeeping, not network species: read them with the state (ph_balance_rivals.balance_pools) for any pH; LAA's two acetic carbons are outside the element audit while latent; the flux audit (rate_nodes) is the unmodified mass action"}
        ph_final_cooled = ph_of_state(final_map, LABEL_TEMPERATURE_K, float(sid), ph_drift, spec)
        metadata.update({'ph_drift_constants': ph_drift.as_dict(), 'strong_ion_difference_mmol_L': float(sid) if sid is not None else None, 'ph_label_declared': ph0, 'ph_label_temperature_K': LABEL_TEMPERATURE_K, 'ph_initial_in_situ': float(ph_series[0]), 'ph_final_in_situ': ph1, 'ph_final_cooled': float(ph_final_cooled), 'ph_series': [float(v) for v in ph_series], 'ph_fixed_point_residual': ph_convergence, 'ph_fixed_point_sweeps': sweeps_run, 'ph_fixed_point_converged': bool(ph_convergence <= PH_FIXED_POINT_FLAG), 'ph_coupling': PH_COUPLING, 'ph_numerics_b60': {'node_grid': PH_NODE_GRID, 'fixed_point': PH_FIXED_POINT, 'relaxation': PH_FIXED_POINT_RELAXATION, 'n_nodes': int(n_nodes)}, 'ionic_strength_M_final': float(node_i[-1]), 'ph_state_corrections_b51': _ph.B51.as_dict(), 'ph_drop_units_cooled': float(ph0 - ph_final_cooled), 'buffer_capacity_initial_mmol_per_pH': buffer_capacity_mmol_per_ph({key: float(y0[SULFUR_INDEX[key]]) for key in SULFUR_STATE_KEYS}, t_k, ph0, ph_drift, spec), 'buffer_capacity_final_mmol_per_pH': buffer_capacity_mmol_per_ph(final_map, t_k, ph1, ph_drift, spec), 'acid_pool_final_mmol_L': final_map.get('ACID', 0.0)})
        if ph_convergence > PH_FIXED_POINT_FLAG:
            import warnings
            warnings.warn(f'pH fixed point not converged: residual {ph_convergence:.3g} pH after {sweeps_run} sweeps (flag {PH_FIXED_POINT_FLAG:g})', PhFixedPointNotConverged, stacklevel=2)
    metadata.update(sulfur_registry_metadata({k: v for k, v in parameters.items() if isinstance(v, SulfurParameter)}))
    run = SulfurRun(times_min=grid, concentrations=concentrations, temperature_k=t_k, ph_initial=ph0, ph_final=ph1, metadata=metadata, ph_series=ph_series, rate_nodes=(np.asarray(node_times, dtype=float), np.asarray(k_nodes, dtype=float)))
    for element in BALANCED_ELEMENTS:
        metadata[f'{element}_closure'] = run.element_closure(element)
    return run

def _node_temperatures(nodes: np.ndarray) -> np.ndarray:
    if profile is None:
        return np.full(len(nodes), t_k)
    return np.interp(nodes, profile[0], profile[1])

def _with_profile_nodes(nodes: np.ndarray) -> np.ndarray:
    if profile is None:
        return nodes
    return np.unique(np.concatenate([nodes, profile_node_times(*profile, duration)]))

